// Normaliza el lead del formulario de renta de aulas antes de escribirlo en Chatwoot.
const b = $json.body ?? $json;

const limpio = (v) => (typeof v === 'string' ? v.trim() : '');

const nombre   = limpio(b.nombre) || 'Lead renta de aulas';
const correo   = limpio(b.correo).toLowerCase();
const personas = limpio(b.personas);
const duracion = limpio(b.duracion);
const notas    = limpio(b.notas);
const fechaIso = limpio(b.fecha);

// Teléfono: nos quedamos con los 10 dígitos nacionales y armamos el E.164
// (+52…), que es el único formato que Chatwoot acepta en phone_number.
const digitos = limpio(b.celular).replace(/\D/g, '');
const nacional =
  digitos.length === 13 && digitos.startsWith('521') ? digitos.slice(3) :
  digitos.length === 12 && digitos.startsWith('52')  ? digitos.slice(2) :
  digitos;
const telefono = nacional.length === 10
  ? `${nacional.slice(0, 2)} ${nacional.slice(2, 6)} ${nacional.slice(6)}`
  : '';
const telefonoE164 = nacional.length === 10 ? `+52${nacional}` : '';
const telefonoDigitos = nacional.length === 10 ? nacional : '';

// Sin correo ni teléfono no hay lead que perseguir: cortamos aquí.
if (!correo && !telefono) return [];

const fecha = fechaIso
  ? new Date(`${fechaIso}T12:00:00`).toLocaleDateString('es-MX', {
      day: 'numeric', month: 'long', year: 'numeric',
    })
  : 'Por definir';

// El dashboard extrae correo y teléfono de los MENSAJES del visitante, no solo
// del contacto, así que el mensaje los repite en texto plano a propósito.
const lineas = [
  'Solicitud de cotización — Renta de aulas (formulario de la web)',
  '',
  `Nombre: ${nombre}`,
  `Personas: ${personas || 'Sin especificar'}`,
  `Fecha tentativa: ${fecha}`,
  `Duración: ${duracion || 'Por definir'}`,
  `Teléfono: ${telefono || 'No dejó'}`,
  `Correo: ${correo || 'No dejó'}`,
];
if (notas) lineas.push(`Notas: ${notas}`);

return [{
  json: {
    nombre, correo, telefono, telefonoE164, telefonoDigitos,
    personas, duracion, notas, fecha, fechaIso,
    mensaje: lineas.join('\n'),
    sourceId: `form-aula-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  },
}];

// El contacto pudo crearse recién o existir de antes: Chatwoot rechaza con 422
// tanto el correo como el teléfono repetidos, por eso "Crear contacto" va con
// onError = continuar y aquí nos quedamos con el id que haya salido.
const lead = $('Preparar lead').first().json;

const creado = $('Crear contacto').first().json;
let contactId = creado?.payload?.contact?.id ?? null;
let existente = null;

if (!contactId) {
  // Buscamos por las dos vías: el choque puede venir del correo O del teléfono.
  const encontrados = [
    ...($('Buscar por correo').first().json?.payload ?? []),
    ...($('Buscar por teléfono').first().json?.payload ?? []),
  ];
  const soloDigitos = (v) => String(v || '').replace(/\D/g, '');
  const match =
    encontrados.find((c) => (c.email || '').toLowerCase() === lead.correo) ??
    encontrados.find(
      (c) => lead.telefonoDigitos && soloDigitos(c.phone_number).endsWith(lead.telefonoDigitos),
    ) ??
    encontrados[0];
  contactId = match?.id ?? null;
  existente = match ?? null;
}

if (!contactId) {
  throw new Error('No se pudo crear ni encontrar el contacto en Chatwoot');
}

// Si el contacto ya existía, SOLO rellenamos lo que le falta: el formulario no
// tiene por qué pisarle el nombre o el correo a una ficha que ya estaba bien.
// Los datos nuevos igual quedan visibles en el mensaje de la conversación.
const nombreAuto = (n) =>
  !n || /^[a-z]+-[a-z]+-\d+$/.test(n.trim()) || /^visitante/i.test(n.trim());

const parche = { custom_attributes: { origen: 'formulario-renta-aulas' } };
if (existente) {
  if (nombreAuto(existente.name) && lead.nombre) parche.name = lead.nombre;
  if (!existente.email && lead.correo) parche.email = lead.correo;
  if (!existente.phone_number && lead.telefonoE164) parche.phone_number = lead.telefonoE164;
}

return [{ json: { ...lead, contactId, parche } }];
